const list = document.getElementById('items');
const empty = document.getElementById('empty');
const input = document.getElementById('new-item');
const msg = document.getElementById('msg');

function render(items) {
  list.replaceChildren();
  for (const item of items) {
    const row = document.createElement('li');
    row.textContent = item.title;
    list.append(row);
  }
  empty.hidden = items.length > 0;
}

async function load() {
  const res = await tessera.call('data.read', {});
  render(Array.isArray(res.data.items) ? res.data.items : []);
}

async function add() {
  const title = input.value.trim();
  if (!title) {
    msg.textContent = 'Type an item first.';
    return;
  }
  try {
    await tessera.call('data.patch', { operations: [{ op: 'add', collection: 'items', record: { title } }] });
    input.value = '';
    msg.textContent = '';
    await load();
  } catch (e) {
    msg.textContent = 'The item could not be added. Please try again.';
  }
}

document.getElementById('add').addEventListener('click', add);
input.addEventListener('keydown', (e) => { if (e.key === 'Enter') add(); });
load().catch(() => { msg.textContent = 'The list could not be loaded.'; });
